1	package org.jsoup.nodes;
2	
3	import org.jsoup.Connection;
4	import org.jsoup.Jsoup;
5	import org.jsoup.integration.TestServer;
6	import org.jsoup.integration.routes.CookieRoute;
7	import org.jsoup.select.Elements;
8	import org.jsoup.select.SelectorTest;
9	import org.junit.jupiter.api.BeforeAll;
10	import org.junit.jupiter.api.Test;
11	
12	import java.io.IOException;
13	import java.util.List;
14	
15	import static org.junit.jupiter.api.Assertions.*;
16	
17	/**
18	 * Tests for FormElement
19	 *
20	 * @author Jonathan Hedley
21	 */
22	public class FormElementTest {
23	    @BeforeAll
24	    public static void setUp() {
25	        TestServer.start();
26	    }
27	
28	    @Test public void hasAssociatedControls() {
29	        //"button", "fieldset", "input", "keygen", "object", "output", "select", "textarea"
30	        String html = "<form id=1><button id=1><fieldset id=2 /><input id=3><keygen id=4><object id=5><output id=6>" +
31	                "<select id=7><option></select><textarea id=8><p id=9>";
32	        Document doc = Jsoup.parse(html);
33	
34	        FormElement form = (FormElement) doc.select("form").first();
35	        assertEquals(8, form.elements().size());
36	    }
37	
38	    @Test public void createsFormData() {
39	        String html = "<form><input name='one' value='two'><select name='three'><option value='not'>" +
40	                "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>" +
41	                "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>" +
42	                "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>" +
43	                "<input name='ten' value='text' disabled>" +
44	                "<input name='eleven' value='text' type='button'>" +
45	                "<input name='twelve' value='text' type='image'>" +
46	                "</form>";
47	        Document doc = Jsoup.parse(html);
48	        FormElement form = (FormElement) doc.select("form").first();
49	        List<Connection.KeyVal> data = form.formData();
50	
51	        assertEquals(6, data.size());
52	        assertEquals("one=two", data.get(0).toString());
53	        assertEquals("three=four", data.get(1).toString());
54	        assertEquals("three=five", data.get(2).toString());
55	        assertEquals("six=seven", data.get(3).toString());
56	        assertEquals("seven=on", data.get(4).toString()); // set
57	        assertEquals("eight=on", data.get(5).toString()); // default
58	        // nine should not appear, not checked checkbox
59	        // ten should not appear, disabled
60	        // eleven should not appear, button
61	    }
62	
63	    @Test public void formDataUsesFirstAttribute() {
64	        String html = "<form><input name=test value=foo name=test2 value=bar>";
65	        Document doc = Jsoup.parse(html);
66	        FormElement form = (FormElement) doc.selectFirst("form");
67	        assertEquals("test=foo", form.formData().get(0).toString());
68	    }
69	
70	    @Test public void createsSubmitableConnection() {
71	        String html = "<form action='/search'><input name='q'></form>";
72	        Document doc = Jsoup.parse(html, "http://example.com/");
73	        doc.select("[name=q]").attr("value", "jsoup");
74	
75	        FormElement form = ((FormElement) doc.select("form").first());
76	        Connection con = form.submit();
77	
78	        assertEquals(Connection.Method.GET, con.request().method());
79	        assertEquals("http://example.com/search", con.request().url().toExternalForm());
80	        List<Connection.KeyVal> dataList = (List<Connection.KeyVal>) con.request().data();
81	        assertEquals("q=jsoup", dataList.get(0).toString());
82	
83	        doc.select("form").attr("method", "post");
84	        Connection con2 = form.submit();
85	        assertEquals(Connection.Method.POST, con2.request().method());
86	    }
87	
88	    @Test public void actionWithNoValue() {
89	        String html = "<form><input name='q'></form>";
90	        Document doc = Jsoup.parse(html, "http://example.com/");
91	        FormElement form = ((FormElement) doc.select("form").first());
92	        Connection con = form.submit();
93	
94	        assertEquals("http://example.com/", con.request().url().toExternalForm());
95	    }
96	
97	    @Test public void actionWithNoBaseUri() {
98	        String html = "<form><input name='q'></form>";
99	        Document doc = Jsoup.parse(html);
100	        FormElement form = ((FormElement) doc.select("form").first());
101	
102	
103	        boolean threw = false;
104	        try {
105	            form.submit();
106	        } catch (IllegalArgumentException e) {
107	            threw = true;
108	            assertEquals("Could not determine a form action URL for submit. Ensure you set a base URI when parsing.",
109	                    e.getMessage());
110	        }
111	        assertTrue(threw);
112	    }
113	
114	    @Test public void formsAddedAfterParseAreFormElements() {
115	        Document doc = Jsoup.parse("<body />");
116	        doc.body().html("<form action='http://example.com/search'><input name='q' value='search'>");
117	        Element formEl = doc.select("form").first();
118	        assertTrue(formEl instanceof FormElement);
119	
120	        FormElement form = (FormElement) formEl;
121	        assertEquals(1, form.elements().size());
122	    }
123	
124	    @Test public void controlsAddedAfterParseAreLinkedWithForms() {
125	        Document doc = Jsoup.parse("<body />");
126	        doc.body().html("<form />");
127	
128	        Element formEl = doc.select("form").first();
129	        formEl.append("<input name=foo value=bar>");
130	
131	        assertTrue(formEl instanceof FormElement);
132	        FormElement form = (FormElement) formEl;
133	        assertEquals(1, form.elements().size());
134	
135	        List<Connection.KeyVal> data = form.formData();
136	        assertEquals("foo=bar", data.get(0).toString());
137	    }
138	
139	    @Test public void usesOnForCheckboxValueIfNoValueSet() {
140	        Document doc = Jsoup.parse("<form><input type=checkbox checked name=foo></form>");
141	        FormElement form = (FormElement) doc.select("form").first();
142	        List<Connection.KeyVal> data = form.formData();
143	        assertEquals("on", data.get(0).value());
144	        assertEquals("foo", data.get(0).key());
145	    }
146	
147	    @Test public void adoptedFormsRetainInputs() {
148	        // test for https://github.com/jhy/jsoup/issues/249
149	        String html = "<html>\n" +
150	                "<body>  \n" +
151	                "  <table>\n" +
152	                "      <form action=\"/hello.php\" method=\"post\">\n" +
153	                "      <tr><td>User:</td><td> <input type=\"text\" name=\"user\" /></td></tr>\n" +
154	                "      <tr><td>Password:</td><td> <input type=\"password\" name=\"pass\" /></td></tr>\n" +
155	                "      <tr><td><input type=\"submit\" name=\"login\" value=\"login\" /></td></tr>\n" +
156	                "   </form>\n" +
157	                "  </table>\n" +
158	                "</body>\n" +
159	                "</html>";
160	        Document doc = Jsoup.parse(html);
161	        FormElement form = (FormElement) doc.select("form").first();
162	        List<Connection.KeyVal> data = form.formData();
163	        assertEquals(3, data.size());
164	        assertEquals("user", data.get(0).key());
165	        assertEquals("pass", data.get(1).key());
166	        assertEquals("login", data.get(2).key());
167	    }
168	
169	    @Test public void removeFormElement() {
170	        String html = "<html>\n" +
171	                "  <body> \n" +
172	                "      <form action=\"/hello.php\" method=\"post\">\n" +
173	                "      User:<input type=\"text\" name=\"user\" />\n" +
174	                "      Password:<input type=\"password\" name=\"pass\" />\n" +
175	                "      <input type=\"submit\" name=\"login\" value=\"login\" />\n" +
176	                "   </form>\n" +
177	                "  </body>\n" +
178	                "</html>  ";
179	        Document doc = Jsoup.parse(html);
180	        FormElement form = (FormElement) doc.selectFirst("form");
181	        Element pass = form.selectFirst("input[name=pass]");
182	        pass.remove();
183	
184	        List<Connection.KeyVal> data = form.formData();
185	        assertEquals(2, data.size());
186	        assertEquals("user", data.get(0).key());
187	        assertEquals("login", data.get(1).key());
188	        assertNull(doc.selectFirst("input[name=pass]"));
189	    }
190	
191	    @Test public void formSubmissionCarriesCookiesFromSession() throws IOException {
192	        String echoUrl = TestServer.origin().echo.url();
193	        Document cookieDoc = Jsoup.connect(TestServer.origin().cookie.url())
194	            .data(CookieRoute.SetCookiesParam, "1")
195	            .get();
196	        Document formDoc = cookieDoc.connection().newRequest() // carries cookies from above set
197	            .url(TestServer.origin().file.url("/htmltests/upload-form.html"))
198	            .get();
199	        FormElement form = formDoc.select("form").forms().get(0);
200	        Document echo = form.submit().post();
201	
202	        assertEquals(echoUrl, echo.location());
203	        Elements els = echo.select("th:contains(Cookie: One)");
204	        // ensure that the cookies are there and in path-specific order (two with same name)
205	        assertEquals("Echo", els.get(0).nextElementSibling().text());
206	        assertEquals("Root", els.get(1).nextElementSibling().text());
207	
208	        // make sure that the session following kept unique requests
209	        assertTrue(cookieDoc.connection().response().url().toExternalForm().contains("Cookie"));
210	        assertTrue(formDoc.connection().response().url().toExternalForm().contains("upload-form"));
211	        assertTrue(echo.connection().response().url().toExternalForm().contains("Echo"));
212	    }
213	
214	    @Test void formElementsAreLive() {
215	        final String html = "<html><body><form><div id=d1><input id=foo name=foo value=none></div><input id=bar name=bar value=one></form></body></html>";
216	        final Document doc = Jsoup.parse(html);
217	        doc.select("#d1").remove();
218	        final FormElement form = (FormElement) doc.selectFirst("form");
219	        form.appendElement("input").attr("id", "baz").attr("name", "baz").attr("value", "two");
220	        SelectorTest.assertSelectedIds(form.elements(), "bar", "baz");
221	
222	        List<Connection.KeyVal> keyVals = form.formData();
223	        assertEquals("one", keyVals.get(0).value());
224	        assertEquals("two", keyVals.get(1).value());
225	    }
