 exempted by an outer fieldset's legend.</p>
 <p>For {@code select} controls: a single select submits the first enabled selected option, or, if none is marked
 selected, the first enabled option; a {@code multiple} select submits all enabled selected options, in order.
 Disabled options, and options within a disabled {@code optgroup}, are not eligible. A select with no eligible
 option contributes no data.</p>
 <p>Checkboxes and radio inputs contribute only when checked. {@code input} controls of type {@code button} and
 {@code image}, and all {@code button} elements, are not submitted; other types (including {@code submit} and
 {@code reset}) are included as before.</p>
 @return a new, independent list of key vals
 */
public List<Connection.KeyVal> formData() {
    ArrayList<Connection.KeyVal> data = new ArrayList<>();

    // iterate the form control elements in document order and accumulate their values
    Elements formEls = elements();
    for (Element el: formEls) {
        if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
        if (el.nameIs("button")) continue; // button elements are never submitted by formData()
        if (el.hasAttr("disabled")) continue; // skip disabled form inputs
        if (inDisabledFieldset(el)) continue; // skip controls held in a disabled fieldset (outside its first legend)
        String name = el.attr("name");
        if (name.length() == 0) continue;
        String type = el.attr("type");

        if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these

        if (el.nameIs("select")) {
            addSelectData(el, name, data);
        } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
            // only add checkbox or radio if they have the checked attribute
            if (el.hasAttr("checked")) {
                final String val = el.val().length() >  0 ? el.val() : "on";
                data.add(HttpConnection.KeyVal.create(name, val));
            }
        } else {
            data.add(HttpConnection.KeyVal.create(name, el.val()));
        }
    }
    return data;
}

private static void addSelectData(Element select, String name, ArrayList<Connection.KeyVal> data) {
    Elements selectedOptions = select.select("option[selected]");
    if (select.hasAttr("multiple")) {
        // submit all enabled selected options, in document order
        for (Element option : selectedOptions) {
            if (isOptionEnabled(option))
                data.add(HttpConnection.KeyVal.create(name, option.val()));
        }
    } else if (!selectedOptions.isEmpty()) {
        // a single select takes the first enabled selected option; if none is enabled, no data is submitted
        for (Element option : selectedOptions) {
            if (isOptionEnabled(option)) {
                data.add(HttpConnection.KeyVal.create(name, option.val()));
                break;
            }
        }
    } else {
        // nothing is marked selected: take the first enabled option, if any
        for (Element option : select.select("option")) {
            if (isOptionEnabled(option)) {
                data.add(HttpConnection.KeyVal.create(name, option.val()));
                break;
            }
        }
    }
}

/**
 An option is enabled if it is not itself disabled, and it is not held within a disabled optgroup.
 */
private static boolean isOptionEnabled(Element option) {
    if (option.hasAttr("disabled")) return false;
    Element parent = option.parent();
    while (parent != null && parent.nameIs("optgroup")) {
        if (parent.hasAttr("disabled")) return false;
        parent = parent.parent();
    }
    return true;
}

/**
 A control is held in a disabled fieldset if any ancestor fieldset is disabled and the control is not a
 descendant of that fieldset's first legend element child. Each disabled ancestor fieldset is checked, so a nested
 disabled fieldset is never exempted by an outer fieldset's legend.
 */
private static boolean inDisabledFieldset(Element control) {
    Element parent = control.parent();
    while (parent != null) {
        if (parent.nameIs("fieldset") && parent.hasAttr("disabled") && !inFirstLegend(parent, control))
            return true;
        parent = parent.parent();
    }
    return false;
}

private static boolean inFirstLegend(Element fieldset, Element control) {
    Element firstLegend = null;
    for (Element child : fieldset.children()) {
        if (child.nameIs("legend")) {
            firstLegend = child;
            break;
        }
    }
    if (firstLegend == null) return false;

    Element parent = control.parent();
    while (parent != null) {
        if (parent == firstLegend) return true;
        if (parent == fieldset) return false;
        parent = parent.parent();
    }
    return false;
}

