        assertNotSame(data1, data2);
        assertEquals(data1.toString(), data2.toString());
        data1.clear(); // mutating one result must not affect a subsequent call
        assertEquals(3, form.formData().size());

        // same-named controls are kept as separate KeyVals, in document order
        assertEquals("dup", data2.get(0).key());
        assertEquals("a", data2.get(0).value());
        assertEquals("dup", data2.get(1).key());
        assertEquals("b", data2.get(1).value());
        assertEquals("s=1", data2.get(2).toString()); // no selected: first option

        // the DOM is untouched
        assertEquals(domBefore, form.html());
    }

    @Test void skipsControlsInDisabledFieldset() {
        String html = "<form><fieldset disabled><input name=off value=x></fieldset>" +
            "<fieldset><input name=on value=y></fieldset></form>";
        FormElement form = (FormElement) Jsoup.parse(html).selectFirst("form");

        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("on=y", data.get(0).toString());
    }

    @Test void allowsControlsInFirstLegendOfDisabledFieldset() {
        String html = "<form><fieldset disabled>" +
            "<legend><input name=legend1 value=a></legend>" +
            "<input name=body value=b>" +
            "<legend><input name=legend2 value=c></legend>" +
            "</fieldset></form>";
        FormElement form = (FormElement) Jsoup.parse(html).selectFirst("form");

        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("legend1=a", data.get(0).toString());
    }

    @Test void nestedDisabledFieldsetIsNotExemptByOuterLegend() {
        // the input sits in the outer fieldset's first legend, but also in a nested disabled fieldset
        String html = "<form><fieldset disabled><legend>" +
            "<fieldset disabled><input name=nested value=x></fieldset>" +
            "</legend><input name=outer value=y></fieldset></form>";
        FormElement form = (FormElement) Jsoup.parse(html).selectFirst("form");

        assertTrue(form.formData().isEmpty());
    }

    @Test void singleSelectSkipsDisabledSelectedOptions() {
        // selected options exist, but the first is disabled: next enabled selected is used
        String html1 = "<form><select name=s><option value=a selected disabled>" +
            "<option value=b selected></select></form>";
        List<Connection.KeyVal> data1 = ((FormElement) Jsoup.parse(html1).selectFirst("form")).formData();
        assertEquals(1, data1.size());
        assertEquals("s=b", data1.get(0).toString());

        // all selected options disabled: no data
        String html2 = "<form><select name=s><option value=a selected disabled>" +
            "<option value=b selected disabled></select></form>";
        assertTrue(((FormElement) Jsoup.parse(html2).selectFirst("form")).formData().isEmpty());

        // nothing selected: first enabled option, skipping disabled ones
        String html3 = "<form><select name=s><option value=a disabled><option value=b></select></form>";
        List<Connection.KeyVal> data3 = ((FormElement) Jsoup.parse(html3).selectFirst("form")).formData();
        assertEquals(1, data3.size());
        assertEquals("s=b", data3.get(0).toString());

        // no options at all: no data
        String html4 = "<form><select name=s></select></form>";
        assertTrue(((FormElement) Jsoup.parse(html4).selectFirst("form")).formData().isEmpty());
    }

    @Test void multipleSelectSubmitsEnabledSelectedOptionsInOrder() {
        String html = "<form><select name=s multiple>" +
            "<option value=a selected disabled>" +
            "<option value=b selected>" +
            "<optgroup disabled><option value=c selected></optgroup>" +
            "<optgroup><option value=d selected></optgroup>" +
            "<option value=e>" + // not selected
            "</select></form>";
        FormElement form = (FormElement) Jsoup.parse(html).selectFirst("form");
        List<Connection.KeyVal> data = form.formData();

        assertEquals(2, data.size());
        assertEquals("s=b", data.get(0).toString());
        assertEquals("s=d", data.get(1).toString());

        // a multiple select with only disabled selections produces no data
        String html2 = "<form><select name=s multiple><option value=a selected disabled></select></form>";
        assertTrue(((FormElement) Jsoup.parse(html2).selectFirst("form")).formData().isEmpty());
    }

    @Test void singleSelectSkipsOptionsInDisabledOptgroup() {
        String html = "<form><select name=s><optgroup disabled><option value=a></optgroup>" +
            "<optgroup><option value=b></optgroup></select></form>";
        FormElement form = (FormElement) Jsoup.parse(html).selectFirst("form");
        List<Connection.KeyVal> data = form.formData();

        assertEquals(1, data.size());
        assertEquals("s=b", data.get(0).toString());
    }

    @Test void buttonElementsAreNotSubmittedButSubmitAndResetInputsAre() {
        String html = "<form>" +
            "<button name=btn value=x>go</button>" +
            "<input name=go type=submit value=Send>" +
            "<input name=reset type=reset value=Clear>" +
            "<input name=img type=image src=x.png>" +
            "<input name=plain type=button value=Nope>" +
            "</form>";
        FormElement form = (FormElement) Jsoup.parse(html).selectFirst("form");
        List<Connection.KeyVal> data = form.formData();

        assertEquals(2, data.size());
        assertEquals("go=Send", data.get(0).toString());
        assertEquals("reset=Clear", data.get(1).toString());
    }
}

